import{_ as r,C as o,o as t,c as d,a0 as a,b as s,w as n,a as c,E as l,a1 as u}from"./chunks/framework.DYS8d9tm.js";const C=JSON.parse('{"title":"💳 Financial Instruments & Transfer Engine Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"technical/architecture/financial_instruments.md","filePath":"technical/architecture/financial_instruments.md"}'),m={name:"technical/architecture/financial_instruments.md"};function p(h,e,g,f,_,y){const i=o("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="💳-financial-instruments-transfer-engine-architecture" tabindex="-1">💳 Financial Instruments &amp; Transfer Engine Architecture <a class="header-anchor" href="#💳-financial-instruments-transfer-engine-architecture" aria-label="Permalink to &quot;💳 Financial Instruments &amp; Transfer Engine Architecture&quot;">​</a></h1><p>This document outlines the architecture, data models, services, and UX parity for specialized financial instruments and cross-account transfer pairing in WealthFam.</p><hr><h2 id="_1-domain-separation-overview" tabindex="-1">1. Domain Separation Overview <a class="header-anchor" href="#_1-domain-separation-overview" aria-label="Permalink to &quot;1. Domain Separation Overview&quot;">​</a></h2><p>Prior to this architecture, credit cards, fixed deposits, and provident funds were treated as generic rows in the <code>accounts</code> table with generic metadata.</p><p>WealthFam implements a <strong>Domain-Separated Instrument Architecture</strong> where:</p><ol><li><code>accounts</code> acts as the universal double-entry ledger root (maintaining running balance, tenant isolation, and ownership).</li><li>Domain extension tables hold specialized instrument metadata and metrics (compounding frequencies, tripartite EPF shares, cycle dates, utilization).</li><li>Specialized services (<code>CreditCardService</code>, <code>FixedDepositService</code>, <code>ProvidentFundService</code>) own instrument lifecycle, analytics, and business rules.</li><li><code>AccountService</code> remains 100% instrument-agnostic.</li></ol>',7)),(t(),s(u,null,{default:n(()=>[l(i,{id:"mermaid-38",class:"mermaid",graph:"erDiagram%0A%20%20%20%20Account%20%7C%7C--o%7C%20CreditCardDetails%20%3A%20%221%3A1%20extension%22%0A%20%20%20%20Account%20%7C%7C--o%7C%20FixedDepositDetails%20%3A%20%221%3A1%20extension%22%0A%20%20%20%20Account%20%7C%7C--o%7C%20ProvidentFundDetails%20%3A%20%221%3A1%20extension%22%0A%20%20%20%20Account%20%7C%7C--o%7B%20Transaction%20%3A%20%221%3AN%20ledger%20entries%22%0A%20%20%20%20Transaction%20%7C%7C--o%7C%20Transaction%20%3A%20%22linked_transaction_id%20(Transfer%20Pair)%22%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-supported-instrument-domains" tabindex="-1">2. Supported Instrument Domains <a class="header-anchor" href="#_2-supported-instrument-domains" aria-label="Permalink to &quot;2. Supported Instrument Domains&quot;">​</a></h2><h3 id="a-credit-cards" tabindex="-1">A. Credit Cards <a class="header-anchor" href="#a-credit-cards" aria-label="Permalink to &quot;A. Credit Cards&quot;">​</a></h3><ul><li><strong>Table</strong>: <code>credit_card_details</code></li><li><strong>Model</strong>: <code>CreditCardDetails</code> (<code>account_id</code>, <code>credit_limit</code>, <code>billing_day</code>, <code>due_day</code>, <code>card_network</code>, <code>card_tier</code>, <code>card_last_4</code>, <code>apr_rate</code>, <code>autopay_enabled</code>)</li><li><strong>Key Concepts</strong>: <ul><li><strong>Single Source of Truth</strong>: User-configured <code>billing_day</code> (1–31) and <code>due_day</code> (1–31) are strictly preserved.</li><li><strong>Dynamic Billing Cycles</strong>: <code>CreditCardService.get_cycle_transactions()</code> supports segmenting transactions into <code>current_unbilled</code>, <code>last_statement</code>, and <code>all</code>.</li><li><strong>Bill Payment</strong>: Dedicated endpoint records double-entry transfers from bank accounts to credit card liabilities.</li></ul></li></ul><h3 id="b-fixed-recurring-deposits-fd-rd" tabindex="-1">B. Fixed &amp; Recurring Deposits (FD / RD) <a class="header-anchor" href="#b-fixed-recurring-deposits-fd-rd" aria-label="Permalink to &quot;B. Fixed &amp; Recurring Deposits (FD / RD)&quot;">​</a></h3><ul><li><strong>Table</strong>: <code>fixed_deposit_details</code></li><li><strong>Model</strong>: <code>FixedDepositDetails</code> (<code>deposit_type</code>, <code>principal_amount</code>, <code>interest_rate</code>, <code>compounding_frequency</code>, <code>start_date</code>, <code>maturity_date</code>, <code>maturity_amount</code>, <code>monthly_deposit</code>)</li><li><strong>Key Concepts</strong>: <ul><li>Compounding frequency math (Monthly, Quarterly, Semi-Annual, Annual).</li><li>Accrued interest simulation up to the current wall-clock date.</li><li>Dynamic progress indicator percentage and days to maturity.</li></ul></li></ul><h3 id="c-provident-funds-epf-ppf-nps" tabindex="-1">C. Provident Funds (EPF / PPF / NPS) <a class="header-anchor" href="#c-provident-funds-epf-ppf-nps" aria-label="Permalink to &quot;C. Provident Funds (EPF / PPF / NPS)&quot;">​</a></h3><ul><li><strong>Table</strong>: <code>provident_fund_details</code></li><li><strong>Model</strong>: <code>ProvidentFundDetails</code> (<code>fund_type</code>, <code>uan_number</code>, <code>pran_number</code>, <code>employee_share</code>, <code>employer_share</code>, <code>pension_share</code>, <code>annual_interest_rate</code>, <code>fy_contributions</code>)</li><li><strong>Key Concepts</strong>: <ul><li>Tripartite balance breakdown for EPF (Employee share, Employer share, EPS Pension share).</li><li>Annual interest estimation based on official statutory rates (e.g. 8.25% EPF, 7.10% PPF).</li><li>Post-tax statutory FY deposit tracking against the ₹1.5L statutory ceiling (PPF / EPF voluntary contributions).</li></ul></li></ul><h3 id="d-loans-liabilities" tabindex="-1">D. Loans &amp; Liabilities <a class="header-anchor" href="#d-loans-liabilities" aria-label="Permalink to &quot;D. Loans &amp; Liabilities&quot;">​</a></h3><ul><li>Enhanced with <code>lender_name</code> and <code>loan_account_number</code> for automated EMI detection and bank transfer linking.</li></ul><hr><h2 id="_3-intelligent-cross-account-transfer-engine" tabindex="-1">3. Intelligent Cross-Account Transfer Engine <a class="header-anchor" href="#_3-intelligent-cross-account-transfer-engine" aria-label="Permalink to &quot;3. Intelligent Cross-Account Transfer Engine&quot;">​</a></h2><p>Transfers between internal family accounts (e.g., Bank → Credit Card bill payment, Bank → Wife&#39;s Bank, Bank → Loan EMI) frequently enter the ledger as two disconnected transactions.</p><h3 id="heuristic-discovery-scoring" tabindex="-1">Heuristic Discovery &amp; Scoring <a class="header-anchor" href="#heuristic-discovery-scoring" aria-label="Permalink to &quot;Heuristic Discovery &amp; Scoring&quot;">​</a></h3><p><code>TransferDetectionService.scan_candidates()</code> inspects unlinked outflows (<code>amount &lt; 0</code>) and inflows (<code>amount &gt; 0</code>) within a configurable lookback window (default 90 days):</p><ul><li><strong>Asymmetric Matching</strong>: <ul><li>Exact match ($\\Delta &lt; ₹0.05$): High base confidence (75%).</li><li>Offer / Discount / Fee tolerance ($\\Delta \\le ₹500$ or ratio $\\ge 0.90$): Flagged with descriptive reason.</li><li>Part-payments: When recipient narrative explicitly cites destination card mask.</li></ul></li><li><strong>Date Proximity</strong>: Same day (+15%), 1 day apart (+10%), within 4 days (+5%).</li><li><strong>Identity &amp; Text Correlation</strong>: Account name mentions, card mask matches ($*1234$), and family member names.</li></ul><h3 id="human-in-the-loop-approval-parity" tabindex="-1">Human-in-the-Loop Approval &amp; Parity <a class="header-anchor" href="#human-in-the-loop-approval-parity" aria-label="Permalink to &quot;Human-in-the-Loop Approval &amp; Parity&quot;">​</a></h3><ul><li><strong>Zero Silent Merges</strong>: In accordance with enterprise audit standards, transfer matches are returned as suggestions for human review.</li><li><strong>Atomic Linking</strong>: When approved (<code>pair_transactions</code>), <code>linked_transaction_id</code> is mutually populated, and <code>exclude_from_reports = True</code> is assigned to both legs to prevent artificial inflation of income or expense totals while preserving double-entry ledger balance.</li><li><strong>Credit Card Dues Sync</strong>: Linking a transfer to a Credit Card automatically deducts the paid amount from <code>total_amount_due</code> and updates <code>min_amount_due</code>. Unlinking safely restores card dues.</li><li><strong>1-Click Counterpart Leg Generation</strong>: When an outflow is recognized as an internal transfer but the destination credit transaction is missing from statements, users can auto-generate the matching credit leg on the target account directly from either Web (<code>Transfers.vue</code>) or Mobile (<code>transfers_hub_screen.dart</code>), with adjustable credited amount for merchant discounts.</li><li><strong>Batch Approvals</strong>: Both Web and Mobile feature 1-click batch approval for high-confidence matches ($\\ge 80%$).</li></ul><hr><h2 id="_4-mobile-web-implementation-parity" tabindex="-1">4. Mobile &amp; Web Implementation Parity <a class="header-anchor" href="#_4-mobile-web-implementation-parity" aria-label="Permalink to &quot;4. Mobile &amp; Web Implementation Parity&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Instrument / Feature</th><th style="text-align:left;">Web Implementation</th><th style="text-align:left;">Mobile Implementation</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Credit Cards</strong></td><td style="text-align:left;"><code>CreditCards.vue</code> &amp; Cycle Filtering</td><td style="text-align:left;">Direct drawer destination (<code>app_shell.dart</code>) &amp; <code>accounts_screen.dart</code></td></tr><tr><td style="text-align:left;"><strong>Deposits (FD / RD)</strong></td><td style="text-align:left;"><code>Deposits.vue</code> with Compounding Math</td><td style="text-align:left;"><code>deposits_screen.dart</code> with KPI strip &amp; maturity telemetry</td></tr><tr><td style="text-align:left;"><strong>Provident Funds</strong></td><td style="text-align:left;"><code>ProvidentFunds.vue</code> with Tripartite EPF</td><td style="text-align:left;"><code>provident_funds_screen.dart</code> &amp; <code>account_detail_screen.dart</code></td></tr><tr><td style="text-align:left;"><strong>Transfers Hub</strong></td><td style="text-align:left;"><code>Transfers.vue</code> (Detected, Unpaired, History)</td><td style="text-align:left;"><code>transfers_hub_screen.dart</code> with Batch Approve &amp; Counterpart Sheet</td></tr><tr><td style="text-align:left;"><strong>Transfer Unlinking</strong></td><td style="text-align:left;">1-Click Unlink with Ledger Rollback</td><td style="text-align:left;">Trailing <code>link_off</code> button with immediate balance refresh</td></tr></tbody></table>',21))])}const v=r(m,[["render",p]]);export{C as __pageData,v as default};
